// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address newManager) public {
        vm.assume(caller != address(0));
        vm.assume(newManager != address(0));
        vm.assume(c.wards(caller) == 0);
        address oldManager = address(c.investmentManager());
        vm.prank(caller);
        try c.file("investmentManager", newManager) {
            assertEq(address(c.investmentManager()), oldManager);
        } catch {
            assert(true);
        }
    }
}
